 const [autoRenew,setAutoRenew]=useState(false);
 const [aiLanguage,setAiLanguage]=useState("Kiswahili"),[aiRecommendations,setAiRecommendations]=useState(null),[aiTranslations,setAiTranslations]=useState(null),[aiBusy,setAiBusy]=useState(false);
 const [notificationForm,setNotificationForm]=useState({title:"Workspace update",message:""});
  const [information,setInformation]=useState([]),[infoForm,setInfoForm]=useState({locationId:"",type:"announcement",title:"",body:"",linkUrl:"",imageUrl:"",visibility:"public",priority:"normal",startsAt:"",endsAt:"",eventCapacity:"0",ticketPriceKES:"0",metadata:{category:"",recordType:"lost",office:"",building:"",floor:"",room:"",openingHours:"",contactPhone:""}});
 const [databaseHealth,setDatabaseHealth]=useState(null);
 const [user,setUser]=useState(null),[data,setData]=useState(null),[subscription,setSubscription]=useState(null),[analytics,setAnalytics]=useState(null),[stock,setStock]=useState({items:[],movements:[]}),[ops,setOps]=useState({appointments:[],visitors:[],tickets:[],campaigns:[]}),[team,setTeam]=useState(null),[auditLogs,setAuditLogs]=useState([]),[advanced,setAdvanced]=useState({rooms:[],tables:[],reservations:[],tableBookings:[],resolutions:[],notifications:[],attendanceReport:null,availability:[]}),[tableForm,setTableForm]=useState({locationId:"",tableNumber:"",seats:"2"}),[resolution,setResolution]=useState({agendaId:"",title:"",decision:"",description:""}),[roomForm,setRoomForm]=useState({locationId:"",roomNumber:"",roomType:"Standard",capacity:"2",ratePerNight:"0"}),[availabilityForm,setAvailabilityForm]=useState({locationId:"",checkIn:"",checkOut:"",roomType:""}),[mode,setMode]=useState("login"),[busy,setBusy]=useState(false),[error,setError]=useState(""),[notice,setNotice]=useState("");
 const [invite,setInvite]=useState({name:"",email:"",role:"editor"}),[inviteUrl,setInviteUrl]=useState("");
 const [newLocation,setNewLocation]=useState({name:"",address:""}),[checkin,setCheckin]=useState({agendaId:"",code:""}),[newStock,setNewStock]=useState({locationId:"",name:"",sku:"",unit:"pcs",quantity:"0",reorderLevel:"5",costPrice:"0"});
 const [discovery,setDiscovery]=useState({locationId:"",deviceType:"qr",identifier:"",targetUrl:""}),[uploading,setUploading]=useState(false);
